def intersection(interval1, interval2):
    """Check if the length of intersection of two intervals is a prime number."""
    # Find the intersection of the two intervals
    start = max(interval1[0], interval2[0])
    end = min(interval1[1], interval2[1])

    # Check if the intervals intersect
    if start > end:
        return "NO"

    # Calculate the length of the intersection
    length = end - start + 1

    # Check if the length is a prime number
    if is_prime(length):
        return "YES"
    else:
        return "NO"

"""
Compare two real numbers represented as integers, floats, or strings.

Args:
    a (int, float, str): The first real number.
    b (int, float, str): The second real number.

Returns:
    int, float, str, or None: The larger variable in its given variable type, or None if the values are equal.
"""

# Replace comma with dot in string inputs
if isinstance(a, str):
    a = a.replace(',', '.')
if isinstance(b, str):
    b = b.replace(',', '.')

# Convert inputs to float
a_float = float(a) if isinstance(a, str) else a
b_float = float(b) if isinstance(b, str) else b

# Compare the values
if a_float > b_float:
    # Return the larger value in its original type
    if isinstance(a, str):
        return a.replace('.', ',')
    else:
        return a
elif a_float < b_float:
    # Return the larger value in its original type
    if isinstance(b, str):
        return b.replace('.', ',')
    else:
        return b
else:
    # Return None if the values are equal
    return None

import hashlib

def string_to_md5(text):
    if not text:
        return None
    return hashlib.md5(text.encode()).hexdigest()
